  "avaliacoes": [
    {
      "id": "E9e45cb13a05b1400",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O guia de inspeção citado trata mangueiras de transferência a granel e seus dispositivos de flutuação como elementos a verificar na operação marítima.",
          "trechos": [
            "E9e45cb13a05b1400:0:694"
          ],
          "condicoes": [
            "No contexto de guia de inspeção offshore do HSE/UK para operações marítimas."
          ],
          "limites": [
            "O trecho não define critérios construtivos, métodos de inspeção detalhados nem periodicidade.",
            "Por ser orientação estrangeira vinculada a referências regulatórias do Reino Unido, não deve ser convertida automaticamente em requisito brasileiro."
          ]
        },
        {
          "proposicao": "Para transferência de metanol, o trecho indica como precauções específicas a inexistência de outras operações simultâneas de carga e a não realização da transferência quando houver risco de descargas atmosféricas.",
          "trechos": [
            "E9e45cb13a05b1400:0:694"
          ],
          "condicoes": [
            "Aplicado explicitamente à transferência de metanol.",
            "Apresentado como item de verificação de procedimento de transferência."
          ],
          "limites": [
            "O excerto não estende essas precauções a todos os produtos a granel.",
            "Não informa critérios adicionais de identificação, embalagem ou segregação de cargas."
          ]
        },
        {
          "proposicao": "O mesmo guia associa início de SIMOPS e pontos de interrupção da operação à necessidade de planejamento prévio e definição de gatilhos para cessação da atividade.",
          "trechos": [
            "E9e45cb13a05b1400:1394:2090",
            "E9e45cb13a05b1400:2090:2223"
          ],
          "condicoes": [
            "No contexto de rig move e operações marítimas planejadas.",
            "Com avaliação de riscos específica da operação."
          ],
          "limites": [
            "O trecho trata de operação marítima de movimentação de unidade, não de procedimento completo de transferência de granéis em FPSO.",
            "Os gatilhos exemplificados não equivalem a limites operacionais universais."
          ]
        }
      ]
    },
    {
      "id": "E543829615f23c3fa",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A integridade de tubulações, válvulas e penetrações de convés/costeado associadas aos sistemas de carga, inertização/blanketing e offloading é apresentada como condição para prevenir perda de contenção.",
          "trechos": [
            "E543829615f23c3fa:0:699"
          ],
          "condicoes": [
            "No contexto de gerenciamento de integridade de FPSOs/FSUs."
          ],
          "limites": [
            "O trecho não especifica métodos de ensaio, critérios quantitativos de aceitação nem limites operacionais.",
            "É orientação de fonte estrangeira, não requisito brasileiro automaticamente aplicável."
          ]
        },
        {
          "proposicao": "O texto recomenda revisões periódicas para identificar mudanças de longo prazo nas características do processo e nas propriedades físicas dos fluidos armazenados em tanques de carga ou slop, de modo a permitir modificações necessárias à manutenção da integridade.",
          "trechos": [
            "E543829615f23c3fa:0:699"
          ],
          "condicoes": [
            "Quando houver potencial variação de características do processo ou da composição/propriedades dos fluidos produzidos e armazenados."
          ],
          "limites": [
            "O excerto não define frequência das revisões nem critérios detalhados de decisão para modificações."
          ]
        },
        {
          "proposicao": "A integridade do sistema de offloading, incluindo mangueira, acoplamento de desconexão marítima, ponto de transferência e espias de amarração do navio aliviador, é vinculada a política do operador para inspeção, manutenção, testes, recertificação e retirada de serviço, considerando recomendações do fabricante, guias setoriais e fatores específicos da instalação.",
          "trechos": [
            "E543829615f23c3fa:699:1397"
          ],
          "condicoes": [
            "Considerando fatores específicos como metocean, carga e número de operações."
          ],
          "limites": [
            "O trecho não fornece vida útil, periodicidade ou critérios numéricos de descarte.",
            "Não aborda identificação, embalagem ou segregação de cargas perigosas."
          ]
        }
      ]
    },
    {
      "id": "E4c0505babdb095cf",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O trecho normativo inclui, entre os procedimentos operacionais normais ou orientações de manuseio de carga, atividades como inertização, gaseificação, resfriamento, carregamento, descarregamento, aquecimento e aeração.",
          "trechos": [
            "E4c0505babdb095cf:0:692"
          ],
          "condicoes": [
            "No contexto de guia ABS para terminais flutuantes offshore de gás liquefeito."
          ],
          "limites": [
            "Refere-se a terminal flutuante de gás liquefeito, não a todo cenário de FPSO de petróleo.",
            "Norma/classificação estrangeira não deve ser tratada como requisito brasileiro geral."
          ]
        },
        {
          "proposicao": "A mesma referência prevê um envelope de condições ambientais limitantes para a realização segura das operações e contempla operações de emergência como vazamento ou derramamento de carga.",
          "trechos": [
            "E4c0505babdb095cf:0:692"
          ],
          "condicoes": [
            "No mesmo contexto normativo de operações de carga/manuseio em terminal flutuante de gás liquefeito."
          ],
          "limites": [
            "O trecho não informa quais são esses limites ambientais nem os procedimentos específicos de resposta.",
            "Não permite reconstruir valores numéricos ausentes."
          ]
        },
        {
          "proposicao": "Para o sistema de tubulação, o texto associa instalação e testes a desenhos e procedimentos aprovados, inspeção visual e ensaios não destrutivos quando requeridos, além de teste hidrostático para comprovar estanqueidade após instalação satisfatória.",
          "trechos": [
            "E4c0505babdb095cf:692:1390",
            "E4c0505babdb095cf:1390:2088"
          ],
          "condicoes": [
            "Aplicado ao contexto da norma ABS e à conclusão de instalação satisfatória."
          ],
          "limites": [
            "O excerto não trata especificamente de mangueiras de transferência.",
            "Por ser trecho normativo de classificação estrangeira, o alcance regulatório local não está estabelecido."
          ]
        }
      ]
    },
    {
      "id": "Ea87edefb4cabce1b",
      "pertinente": false,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Os trechos sobre atmosfera inflamável, perda de contenção e integridade de sistemas de carga/offloading são correlatos ao mesmo documento já representado por outra fonte desta rodada.",
          "trechos": [
            "Ea87edefb4cabce1b:1393:2092",
            "Ea87edefb4cabce1b:2092:2403"
          ],
          "condicoes": [
            "Documento identificado como o mesmo guia de integridade de FPSOs/FSUs já avaliado."
          ],
          "limites": [
            "Não deve ser tratado como estudo independente adicional.",
            "Aproveitamento didático deve evitar duplicação de evidência."
          ]
        }
      ]
    },
    {
      "id": "E954335b9e1f0dd82",
      "pertinente": false,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O texto descreve ferramenta de simulação e otimização para programação de embarcações de suprimento, com experimento indicando viabilidade do uso de múltiplas cargas e potencial ganho de custo mantendo nível equivalente de serviço.",
          "trechos": [
            "E954335b9e1f0dd82:1391:2084",
            "E954335b9e1f0dd82:2084:2336"
          ],
          "condicoes": [
            "No contexto de experimentos com ferramenta de apoio à decisão logística."
          ],
          "limites": [
            "Não aborda identificação, embalagem, segregação, mangueiras ou prevenção de derramamentos.",
            "Resultado experimental do modelo não equivale a regra operacional universal."
          ]
        }
      ]
    },
    {
      "id": "Ee3881801b16d5e3b",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na logística offshore descrita, o alívio do óleo armazenado em FPSOs é realizado por navios aliviadores, e em muitas situações pode haver necessidade de rebocadores durante a transferência para evitar colisão entre o navio aliviador e o FPSO.",
          "trechos": [
            "Ee3881801b16d5e3b:698:1398"
          ],
          "condicoes": [
            "No contexto de FPSOs operando em águas profundas e distantes da costa.",
            "Quando a transferência de óleo do FPSO para o shuttle tanker está em curso."
          ],
          "limites": [
            "O próprio texto usa formulação de frequência não absoluta, portanto não indica necessidade em todos os casos.",
            "O trecho não detalha mangueiras, arranjo de transferência nem critérios de prevenção de derrames."
          ]
        },
        {
          "proposicao": "Aspectos climáticos são apresentados como fatores que influenciam dificuldade, duração e até a ocorrência de tarefas offshore, podendo levar à interrupção de operações de sondas e unidades de produção quando as condições de mar ultrapassam limites de segurança.",
          "trechos": [
            "Ee3881801b16d5e3b:0:698",
            "Ee3881801b16d5e3b:1398:2089",
            "Ee3881801b16d5e3b:2089:2236"
          ],
          "condicoes": [
            "Quando houver condições ambientais adversas.",
            "Se a altura de onda ultrapassar limites de segurança, segundo o trecho."
          ],
          "limites": [
            "Os limites não são quantificados no excerto.",
            "A passagem trata de influência operacional geral do clima, não de requisitos específicos para uma carga ou produto perigoso."
          ]
        }
      ]
    }
  ],
